    if (it == videoIdToVideo.cend())
      return "-1";
    ++videoIdToViews[videoId];
    const string video = it->second;
    const int duration =
        min(endMinute, static_cast<int>(video.length()) - 1) - startMinute + 1;
    return video.substr(startMinute, duration);
  }

