          if (heights[stack.top()][j] == heights[i][j])
            hasEqualHeight = true;
          ++ans[stack.top()][j], stack.pop();
        }
        if (!stack.empty() && !hasEqualHeight)
          ++ans[stack.top()][j];
        stack.push(i);
      }
    }

